function updatePlayback(){$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'一時停止':'分割アニメーションを再生');$('play-label').textContent=playing?'分割しています':'分割を眺める';$('progress').style.width=`${model?.events.length?index/model.events.length*100:100}%`;$('count').textContent=visible.size.toLocaleString();$('step-count').textContent=model&&index<model.events.length?`${index} / ${model.events.length}`:'完成';$('play').disabled=!model?.events.length;$('restart').disabled=!model?.events.length;}
