document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{config.mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(t=>t.setAttribute('aria-pressed',t===b));$('mode-description').textContent={basic:'いちばん大きな正方形から、順番に。',mosaic:'大小の四角がつくる、気まぐれなリズム。',focus:'ひとつの場所へ、小さな四角が集まる。'}[config.mode];$('focus-tool').disabled=config.mode!=='focus';$('strength').disabled=config.mode!=='focus';if(config.mode!=='focus')setTool('select');rebuild();});
for(const id of['detail','strength']){$(id).oninput=()=>{$(`${id}-value`).value=$(id).value;};$(id).onchange=()=>{config[id]=Number($(id).value);rebuild({fit:false});};}
$('palette').onchange=draw;$('outlines').onchange=draw;$('speed').oninput=()=>{$('speed-value').value=`${$('speed').value}×`;};$('seed').onchange=()=>{config.seed=$('seed').value;rebuild({fit:false});};$('shuffle').onclick=()=>{config.seed=String(crypto.getRandomValues(new Uint32Array(1))[0]);$('seed').value=config.seed;rebuild();};
