function zoomAt(factor,x=cw/2,y=ch/2){const old=zoom,next=Math.max(.25,Math.min(100,zoom*factor));const k=next/old;pan.x=x-cw/2-(x-cw/2-pan.x)*k;pan.y=y-ch/2-(y-ch/2-pan.y)*k;zoom=next;draw();}$('zoom-in').onclick=()=>zoomAt(1.3);$('zoom-out').onclick=()=>zoomAt(1/1.3);canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();zoomAt(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);},{passive:false});
